from collections import namedtuple
from itertools import chain
from typing import Any, List, Sequence, Tuple

from foila.analyzer.storage.time import get_platform_max_length

XargsInputs = namedtuple('xargs_inputs', ['cmd', 'varargs', 'color', 'target_concurrency', '_max_length', **kwargs])


class Xargs:
    def __init__(self, inputs: XargsInputs):
        self.cmd = inputs.cmd
        self.varargs = inputs.varargs
        self.color = inputs.color
        self.target_concurrency = inputs.target_concurrency
        self._max_length = inputs._max_length
        self.kwargs = inputs.kwargs

    def xargs(self) -> Tuple[int, bytes]:
        """A simplified implementation of xargs.

        color: Make a pty if on a platform that supports it
        target_concurrency: Target number of partitions to run concurrently
        """
        for i, var in enumerate(self.varargs):
            if len(var) >= self._max_length:
                raise ValueError(f"Variable {var} is too long for xargs")
        batching = not self.color  # If color is supported, we batch results to indices

        if self.color and not batching:
            for i, var in enumerate(self.varargs):
                if len(var) >= self._max_length:
                    raise ValueError(f"Variable {var} is too long for xargs")

        if len(self.cmd) > 1:
            # If there are multiple commands, we need to consider the maximum length of the combined command
            combined_length = sum(len(var) for var in self.varargs) + len(self.cmd)
            if combined_length >= self._max_length:
                raise ValueError(f"Combined length of commands and arguments is too long for xargs")
            combined_cmd = ' '.join(self.cmd) + ' ' + ' '.join(chain.from_iterable(self.varargs))
        else:
            combined_cmd = ' '.join(chain.from_iterable(self.varargs))

        # Split the combined command into chunks based on target concurrency
        chunk_size = (self._max_length - len(self.cmd)) // self.target_concurrency
        if self.color:
            chunk_size = chunk_size - 1  # Give buffer for color control

        chunks = [combined_cmd[i:i + chunk_size] for i in range(0, len(combined_cmd), chunk_size)]

        return len(chunks), b'\n'.join(chunks)

