def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    def dfs(cls):
        if cls in seen:
            return []
        seen.add(cls)
        return [dfs(base) for base in cls.__bases__]

    base_classes = dfs(classes[-1])
    return [cls for cls in classes if cls in base_classes]

