def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""

    # check which digests are in the manifest file
    present_digests = {digest for digest in digests_used if digest in manifest_files}

    # check which digests are present and used in the manifest file
    used_digests = {
        digest for manifest_file in manifest_files for digest in manifest_file.get_digests()
        if digest in present_digests
    }

    # check if all digests used are present and used in the manifest file
    if used_digests != digests_used:
        raise DigestError("Not all digests used in the manifest file are present.")

