from datetime import datetime, timezone

class Time:
    def __init__(self, ticks, tz=None):
        """Create a time from ticks (nanoseconds since midnight).

        :param ticks: nanoseconds since midnight
        :type ticks: int
        :param tz: optional timezone
        :type tz: datetime.tzinfo

        :rtype: Time

        :raises ValueError: if ticks is out of bounds
            (0 <= ticks < 86400000000000)
        """
        if not isinstance(ticks, int): raise TypeError('ticks must be an integer')
        if ticks < 0 or ticks >= 86400000000000: raise ValueError('ticks must be between 0 and 86400000000000')
        if not tz: tz = timezone.utc
        self.ticks = ticks
        self.tz = tz

    @property
    def timestamp(self):
        """Return the timestamp of the time."""
        return datetime.fromtimestamp(self.ticks / 1000000000, self.tz)

