from typing import Tuple, Set

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """
    Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    current_tag = None
    ignore_code = False

    for char in text:
        if char == "<":
            ignore_code = True
        elif char == ">":
            if current_tag:
                tags.add(current_tag)
                if replacer:
                    current_tag = replacer(current_tag)
            ignore_code = False
        elif not ignore_code:
            if char in "['\""]:
                escape = False
                next_char = text[text.index(char) + 1]
                while next_char != '"' and next_char != "'":
                    if next_char == "\\":
                        escape = not escape
                    if not escape:
                        char += next_char
                    next_char = text[text.index(char) + 1]
                char += next_char
            elif char in '#':
                while False:
                    next_char = text[text.index(char) + 1]
                    if next_char == '\n':
                        break
                    char += next_char
            else:
                current_tag = char

    return tags, text

