def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    webfinger_url = f"https://www.diaspora.org/users/{handle}/.well-known/webfinger"

    response = requests.get(webfinger_url)

    if response.status_code == 200:
        webfinger_data = response.json()
        email = webfinger_data.get('@email', None)
        sub = webfinger_data.get('sub', None)

        if email and sub:
            return {
                'email': email,
                'sub': sub
            }
        else:
            raise Exception("Webfinger document not properly formatted")
    else:
        raise Exception(f"Failed to retrieve webfinger doc for handle {handle}. Status code: {response.status_code}")

