from typing import Dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    flatten_dict = {}
    for root, dirs, files in os.walk(plugin_dir):
        for file in files:
            if file.startswith('__') or file.endswith('~') or file.startswith('.'):
                continue
            file_path = os.path.join(root, file)
            with open(file_path, 'r', encoding='utf-8') as f:
                file_content = f.read()
                properties = {}
                for line in file_content.split('\n'):
                    line = line.strip()
                    if line:
                        key, value = line.split('=', maxsplit=1)
                        properties[key.strip()] = value.strip()
                flatten_dict.update(properties)
    return flatten_dict

